31	func viewNumber(m *protos.Message) uint64 {
32		if pp := m.GetPrePrepare(); pp != nil {
33			return pp.GetView()
34		}
35	
36		if prp := m.GetPrepare(); prp != nil {
37			return prp.GetView()
38		}
39	
40		if cmt := m.GetCommit(); cmt != nil {
41			return cmt.GetView()
42		}
43	
44		return math.MaxUint64
45	}
46	
47	func proposalSequence(m *protos.Message) uint64 {
48		if pp := m.GetPrePrepare(); pp != nil {
49			return pp.Seq
50		}
51	
52		if prp := m.GetPrepare(); prp != nil {
53			return prp.Seq
54		}
55	
56		if cmt := m.GetCommit(); cmt != nil {
57			return cmt.Seq
58		}
59	
60		return math.MaxUint64
61	}
