283			Decider:            pm.Decider,
284			FailureDetector:    pm.FailureDetector,
285			Sync:               pm.Sync,
286			Logger:             pm.Logger,
287			Comm:               pm.Comm,
288			Verifier:           pm.Verifier,
289			Signer:             pm.Signer,
290			MembershipNotifier: pm.MembershipNotifier,
291			ProposalSequence:   proposalSequence,
292			DecisionsInView:    decisionsInView,
293			State:              pm.State,
294			InMsgQSize:         pm.InMsqQSize,
295			ViewSequences:      pm.ViewSequences,
296			MetricsBlacklist:   pm.MetricsBlacklist,
297			MetricsView:        pm.MetricsView,
298		}
299	
300		view.ViewSequences.Store(ViewSequence{
301			ViewActive:  true,
302			ProposalSeq: proposalSequence,
303		})
304	
305		pm.restoreOnceFromWAL.Do(func() {
306			err := pm.State.Restore(view)
