415	type blacklist struct {
416		currentLeader      uint64
417		leaderRotation     bool
418		prevMD             *protos.ViewMetadata
419		n                  uint64
420		nodes              []uint64
421		currView           uint64
422		preparesFrom       map[uint64]*protos.PreparesFrom
423		logger             api.Logger
424		metricsBlacklist   *api.MetricsBlacklist
425		f                  int
426		decisionsPerLeader uint64
427	}
428	
429	func (bl blacklist) computeUpdate() []uint64 {
430		newBlacklist := bl.prevMD.BlackList
431		viewBeforeViewChanges := bl.prevMD.ViewId
432	
433		bl.logger.Debugf("view before: %d, current view: %d", viewBeforeViewChanges, bl.currView)
434	
435		// In case the previous view is different from this view, then we had a view change.
436		// Thus, we need to add some nodes to the blacklist.
437		if viewBeforeViewChanges != bl.currView {
438			// If we are in the first proposal, then the leader ID of the previous view is not computed with an offset.
439			// However, if we are in any subsequent proposal, then the previous leader's ID was computed by adding 1 to the
440			// latest decisions in view that was committed.
441			offset := uint64(1)
442			if bl.prevMD.LatestSequence == 0 {
443				offset = 0
444			}
445	
446			// Locate every leader of all views previous to this views.
447			for viewPreviousToThisView := viewBeforeViewChanges; viewPreviousToThisView < bl.currView; viewPreviousToThisView++ {
448				bl.logger.Debugf("viewPreviousToThisView: %d, N: %d, Nodes: %v, rotation: %v, decisions in view: %d, decisions per leader: %d, blacklist: %v",
449					viewPreviousToThisView, bl.n, bl.nodes, bl.leaderRotation, bl.prevMD.DecisionsInView, bl.decisionsPerLeader, bl.prevMD.BlackList)
450				leaderID := getLeaderID(viewPreviousToThisView, bl.n, bl.nodes, bl.leaderRotation, bl.prevMD.DecisionsInView+offset, bl.decisionsPerLeader, bl.prevMD.BlackList)
451				if leaderID == bl.currentLeader {
452					bl.logger.Debugf("Skipping blacklisting current node (%d)", leaderID)
453					continue
454				}
455				// Add that leader to the blacklist, because it did not drive any proposal, hence we skipped it because of view changes.
456				newBlacklist = append(newBlacklist, leaderID)
457				bl.logger.Infof("Blacklisting %d", leaderID)
458			}
459		} else {
460			// We are in the same view, hence we can remove some nodes from the blacklist, if applicable,
461			// because they helped us drive from the previous sequence to this sequence.
462			// Compute the new blacklist according to your collected attestations on prepares sent
463			// in previous round.
464			newBlacklist = pruneBlacklist(newBlacklist, bl.preparesFrom, bl.f, bl.nodes, bl.logger)
465		}
466	
467		// If blacklist is too big, remove items from its beginning
468		for len(newBlacklist) > bl.f {
469			bl.logger.Infof("Removing %d from %d sized blacklist due to size constraint", newBlacklist[0], len(newBlacklist))
470			newBlacklist = newBlacklist[1:]
471		}
472	
473		if len(bl.prevMD.BlackList) != len(newBlacklist) {
474			bl.logger.Infof("Blacklist changed: %v --> %v", bl.prevMD.BlackList, newBlacklist)
475		}
476	
477		newBlacklistMap := make(map[uint64]bool, len(newBlacklist))
478		for _, node := range newBlacklist {
479			newBlacklistMap[node] = true
480		}
481		for _, node := range bl.nodes {
482			inBlacklist := newBlacklistMap[node]
483			bl.metricsBlacklist.NodesInBlackList.With(
484				bl.metricsBlacklist.LabelsForWith("blackid", strconv.FormatUint(node, 10))...,
485			).Set(btoi(inBlacklist))
486		}
487		bl.metricsBlacklist.CountBlackList.Set(float64(len(newBlacklist)))
488	
489		return newBlacklist
490	}
491	
492	func btoi(b bool) float64 {
493		if b {
494			return 1
495		}
496		return 0
497	}
498	
499	// pruneBlacklist receives the previous blacklist, prepare acknowledgements from nodes, and returns
500	// the new blacklist such that a node that was observed by more than f observers is removed from the blacklist,
501	// and all nodes that no longer exist are also removed from the blacklist.
502	func pruneBlacklist(prevBlacklist []uint64, preparesFrom map[uint64]*protos.PreparesFrom, f int, nodes []uint64, logger api.Logger) []uint64 {
503		if len(prevBlacklist) == 0 {
504			logger.Debugf("Blacklist empty, nothing to prune")
505			return prevBlacklist
506		}
507		logger.Debugf("Pruning blacklist %v with %d acknowledgements, f=%d, n=%d", prevBlacklist, len(preparesFrom), f, len(nodes))
508		// Build a set of all nodes
509		currentNodeIDs := make(map[uint64]struct{})
510		for _, n := range nodes {
511			currentNodeIDs[n] = struct{}{}
512		}
513	
514		// For each sender of a prepare, count the number of commit signatures which acknowledge receiving a prepare from it.
515		nodeID2Acks := make(map[uint64]int)
516		for from, gotPrepareFrom := range preparesFrom {
517			logger.Debugf("%d observed prepares from %v", from, gotPrepareFrom)
518			for _, prepareSender := range gotPrepareFrom.Ids {
519				nodeID2Acks[prepareSender]++
520			}
521		}
522	
523		var newBlackList []uint64
524		for _, blackListedNode := range prevBlacklist {
525			// Purge nodes that were removed by a reconfiguration
526			if _, exists := currentNodeIDs[blackListedNode]; !exists {
527				logger.Infof("Node %d no longer exists, removing it from the blacklist", blackListedNode)
528				continue
529			}
530	
531			// Purge nodes that have enough attestations of being alive
532			observers := nodeID2Acks[blackListedNode]
533			if observers > f {
534				logger.Infof("Node %d was observed sending a prepare by %d nodes, removing it from blacklist", blackListedNode, observers)
535				continue
536			}
537			newBlackList = append(newBlackList, blackListedNode)
538		}
539	
540		return newBlackList
541	}
