668	func (v *ViewChanger) extractCurrentSequence() (uint64, *protos.Proposal) {
669		myMetadata := &protos.ViewMetadata{}
670		myLastDesicion, _ := v.Checkpoint.Get()
671		if myLastDesicion.Metadata == nil {
672			return 0, myLastDesicion
673		}
674		if err := proto.Unmarshal(myLastDesicion.Metadata, myMetadata); err != nil {
675			v.Logger.Panicf("Node %d is unable to unmarshal its own last decision metadata from checkpoint, err: %v", v.SelfID, err)
676		}
677		return myMetadata.LatestSequence, myLastDesicion
678	}
