1110	func (v *ViewChanger) processNewViewMsg(msg *protos.NewView) {
1111		valid, calledSync, calledDeliver := v.validateNewViewMsg(msg)
1112		for calledDeliver {
1113			v.Logger.Debugf("Node %d is processing a newView message, and delivered a proposal", v.SelfID)
1114			valid, calledSync, calledDeliver = v.validateNewViewMsg(msg)
1115		}
1116		if !valid {
1117			v.Logger.Warnf("Node %d is processing a newView message, but the message is invalid", v.SelfID)
1118			return
1119		}
1120		if calledSync {
1121			v.Logger.Debugf("Node %d is processing a newView message, and requested a sync", v.SelfID)
1122			return
1123		}
1124	
1125		ok, noInFlight, inFlightProposal, err := CheckInFlight(v.extractViewDataMessages(msg), v.f, v.quorum, v.N, v.Verifier)
1126		if err != nil {
1127			v.Logger.Panicf("The check of the in flight proposal by node %d returned an error: %v", v.SelfID, err)
1128		}
1129		if !ok {
1130			v.Logger.Debugf("The check of the in flight proposal by node %d did not pass", v.SelfID)
1131			return
1132		}
1133	
1134		if !noInFlight && !v.commitInFlightProposal(inFlightProposal) {
1135			v.Logger.Warnf("Node %d was unable to commit the in flight proposal, not changing the view", v.SelfID)
1136			return
1137		}
1138	
1139		mySequence, _ := v.extractCurrentSequence()
1140	
1141		newViewToSave := &protos.SavedMessage{
1142			Content: &protos.SavedMessage_NewView{
1143				NewView: &protos.ViewMetadata{
1144					ViewId:         v.currView,
1145					LatestSequence: mySequence,
1146				},

680				return fmt.Errorf("blacklist changed (%v --> %v) during membership change", prevProposalMetadata.BlackList, pendingBlacklist)
681			}
682			v.Logger.Infof("Skipping verifying prev commits due to membership change")
683			return nil
684		}
685	
686		_, f := computeQuorum(v.N)
687	
688		if v.blacklistingSupported(f, myLastCommitSignatures) && len(prevCommitSignatures) < len(myLastCommitSignatures) {
689			return fmt.Errorf("only %d out of %d required previous commits is included in pre-prepare",
690				len(prevCommitSignatures), len(myLastCommitSignatures))
691		}
692	
693		// We previously verified the previous commit signatures, now we need to ensure that the blacklist
694		// of this proposal is obtained by applying the deterministic blacklist maintenance algorithm
695		// on the blacklist of the previous proposal which has been committed.
696	
697		blacklist := &blacklist{
698			currentLeader:      v.LeaderID,
699			leaderRotation:     v.DecisionsPerLeader > 0,
700			n:                  v.N,
701			prevMD:             prevProposalMetadata,
702			decisionsPerLeader: v.DecisionsPerLeader,
703			preparesFrom:       prepareAcknowledgements,
704			f:                  f,
705			logger:             v.Logger,
706			metricsBlacklist:   v.MetricsBlacklist,
707			nodes:              v.NodesList,
708			currView:           v.Number,
709		}
710	
711		expectedBlacklist := blacklist.computeUpdate()
712		if !slices.Equal(pendingBlacklist, expectedBlacklist) {
713			return fmt.Errorf("proposed blacklist %v differs from expected %v blacklist", pendingBlacklist, expectedBlacklist)
714		}
715	
716		return nil
717	}
