115	func (ps *PersistedState) Restore(v *View) error {
116		// Unless we conclude otherwise, we're in a COMMITTED state
117		v.Phase = COMMITTED
118	
119		entries := ps.Entries
120		if len(entries) == 0 {
121			ps.Logger.Infof("Nothing to restore")
122			return nil
123		}
124	
125		ps.Logger.Infof("WAL contains %d entries", len(entries))
126	
127		lastEntry := entries[len(entries)-1]
128		lastPersistedMessage := &protos.SavedMessage{}
129		if err := proto.Unmarshal(lastEntry, lastPersistedMessage); err != nil {
130			ps.Logger.Errorf("Failed unmarshaling last entry from WAL: %v", err)
131			return fmt.Errorf("failed unmarshaling last entry from WAL: %w", err)
132		}
133	
134		if proposed := lastPersistedMessage.GetProposedRecord(); proposed != nil {
135			return ps.recoverProposed(proposed, v)
136		}
137	
138		if commitMsg := lastPersistedMessage.GetCommit(); commitMsg != nil {
139			return ps.recoverPrepared(commitMsg, v, entries)
140		}
141	
142		if newViewMsg := lastPersistedMessage.GetNewView(); newViewMsg != nil {
143			ps.Logger.Infof("last entry in WAL is a newView record")
144			return nil
145		}
146	
147		if viewChangeMsg := lastPersistedMessage.GetViewChange(); viewChangeMsg != nil {
148			ps.Logger.Infof("last entry in WAL is a viewChange message")
149			return nil
150		}
151	
152		return fmt.Errorf("unrecognized record: %v", lastPersistedMessage)
153	}
