155	func (ps *PersistedState) recoverProposed(lastPersistedMessage *protos.ProposedRecord, v *View) error {
156		prop := lastPersistedMessage.GetPrePrepare().Proposal
157		v.inFlightProposal = &types.Proposal{
158			VerificationSequence: int64(prop.VerificationSequence),
159			Metadata:             prop.Metadata,
160			Payload:              prop.Payload,
161			Header:               prop.Header,
162		}
163		ps.storeProposal(lastPersistedMessage)
164		// Reconstruct the prepare message we shall next broadcast
165		// after the recovery.
166		prp := lastPersistedMessage.GetPrePrepare()
167		v.lastBroadcastSent = &protos.Message{
168			Content: &protos.Message_Prepare{
169				Prepare: lastPersistedMessage.GetPrepare(),
170			},
171		}
172		v.Phase = PROPOSED
173		v.Number = prp.View
174		v.ProposalSequence = prp.Seq
175		md := &protos.ViewMetadata{}
176		if err := proto.Unmarshal(prop.Metadata, md); err != nil {
177			ps.Logger.Panicf("Failed to unmarshal proposal metadata, error: %v", err)
178		}
179		v.DecisionsInView = md.DecisionsInView
180		ps.Logger.Infof("Restored proposal with sequence %d", lastPersistedMessage.GetPrePrepare().Seq)
181		return nil
182	}
